import{_ as e,o,c as a,ah as i}from"./chunks/framework.D4KxWb5R.js";const u=JSON.parse('{"title":"Notifications","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/notifications.md","filePath":"src/en/guide/notifications.md"}'),n={name:"en/guide/notifications.md"};function r(s,t,d,h,c,l){return o(),a("div",null,[...t[0]||(t[0]=[i('<h1 id="notifications" tabindex="-1">Notifications <a class="header-anchor" href="#notifications" aria-label="Permalink to &quot;Notifications&quot;">​</a></h1><p>M&#39;City IQ tells you about what concerns you: in the app and, if you wish, by e-mail. You are never notified of your own actions.</p><h2 id="the-bell" tabindex="-1">The bell <a class="header-anchor" href="#the-bell" aria-label="Permalink to &quot;The bell&quot;">​</a></h2><p>The bell in the header shows the number of unread notifications and the ten latest. It refreshes on its own every minute.</p><ul><li>Click a notification to open it: it is marked as read and takes you to the page concerned.</li><li><strong>Mark all as read</strong> clears the counter.</li><li><strong>See all notifications</strong> opens the Notifications page.</li></ul><h2 id="the-notifications-page" tabindex="-1">The Notifications page <a class="header-anchor" href="#the-notifications-page" aria-label="Permalink to &quot;The Notifications page&quot;">​</a></h2><p>It lists all your notifications, with the <strong>All</strong> and <strong>Unread</strong> filters and a link to the <strong>Settings</strong>. Notifications are shown in your working language. Those read more than 90 days ago are deleted automatically.</p><h2 id="what-you-are-notified-of" tabindex="-1">What you are notified of <a class="header-anchor" href="#what-you-are-notified-of" aria-label="Permalink to &quot;What you are notified of&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Event</th><th>Who is notified</th><th>E-mail by default</th></tr></thead><tbody><tr><td>Communications</td><td>The recipients of a published communication</td><td>No</td></tr><tr><td>Shared resources</td><td>The accounts whose scope covers the resource</td><td>No</td></tr><tr><td>Contact messages</td><td>Those who handle messages (CEO, Support head, Support L1)</td><td>Yes</td></tr><tr><td>Desynchronized products</td><td>The CEO and the members of the product&#39;s teams</td><td>Yes</td></tr><tr><td>Indicator collection</td><td>After three failures in a row: the CEO and the product&#39;s teams</td><td>Yes</td></tr><tr><td>Teams</td><td>The account added to or removed from a team</td><td>No</td></tr><tr><td>Your access</td><td>The account whose position, department, scope or back-office access changes</td><td>Yes</td></tr></tbody></table><p>A desynchronized-product alert also shows as a banner on the desk.</p><h2 id="choosing-how-you-are-notified" tabindex="-1">Choosing how you are notified <a class="header-anchor" href="#choosing-how-you-are-notified" aria-label="Permalink to &quot;Choosing how you are notified&quot;">​</a></h2><p>In <strong>Settings → Notifications</strong>, tick <strong>In the app</strong> and/or <strong>By e-mail</strong> for each event, then save. The list shows only the events your position can receive.</p>',12)])])}const p=e(n,[["render",r]]);export{u as __pageData,p as default};
